    for (int i = 1; i < (string.length() - 1); i++) {
        final char c = string.charAt(i);
        if (hadBackSlash) {
            if (c == '\\') {
                stringBuilder.append('\\');
            } else if (c == '"') {
                stringBuilder.append('"');
            } else if (c == '\'') {
                stringBuilder.append('\'');
            } else if (c == 'x') {
