PgmFileInfo(final int width, final int height, final boolean rawbits, final int max) throws ImageReadException {
    super(width, height, rawbits);
    if (max <= 0) {
        throw new ImageReadException("PGM maxVal " + max
                + " is out of range [1;65535]");
    }
    if (max <= 255) {
        scale = 255f;
        bytesPerSample = 1;
    } else if (max <= 65535) {
        scale = 65535f;
        bytesPerSample = 2;
    } else {
        throw new ImageReadException("PGM maxVal " + max
                + " is out of range [1;65535]");
    }
    this.max = max;
