                    break;

                case TiffDirectoryConstants.DIRECTORY_TYPE_GPS:
                    if (gpsDirectory != null) {
                        throw new ImageWriteException(
                                "More than one GPS directory.");
                    }
                    gpsDirectory = directory;
                    break;

