                    throw new ImageWriteException("Unknown directory: "
                            + dirType);
            }
        } else {
            if (directoryIndices.contains(dirType)) {
                throw new ImageWriteException(
                        "More than one directory with index: " + dirType
                                + ".");
            }
            directoryIndices.add(dirType);
