                  pngChunkScal.unitsPerPixelYAxis);
        } else {
            physicalScale = PhysicalScale.createFromRadians(pngChunkScal.unitsPerPixelXAxis,
                  pngChunkScal.unitsPerPixelYAxis);
        }
