    } else if (marker == JpegConstants.DHT_MARKER) {
        final DhtSegment dhtSegment = new DhtSegment(marker, segmentData);
        for (final HuffmanTable table : dhtSegment.huffmanTables) {
            DhtSegment.HuffmanTable[] tables;
